"""FACAI v2: interactive coverage, device concept and complete image galleries."""
from pathlib import Path
from html import escape
import json, hashlib
from content_settings import SERVICES_CONTENT

ROOT = Path(__file__).resolve().parents[1]
CATALOG = json.loads((ROOT/'content/media-catalog.json').read_text(encoding='utf-8'))
PHOTOS = {a['id']:a for a in CATALOG if a['tipo']=='foto'}
SERVICE_PHOTOS = {'transporte-carga.html':[42,43,44,45], 'transporte-maquinaria.html':[57,28,29,30], 'carga-proyecto.html':[46,47,48,2,14], 'transporte-cama-baja.html':[40,41,31,32], 'transporte-puertos.html':[58,59,60,61], 'cargas-consolidadas.html':[1,4,5]}

# Existing photos retain their optimized dimensions; new uploads are decoded and
# re-encoded without metadata before appearing in the public build.
for page, settings in SERVICES_CONTENT.items():
    ids=[]
    for entry in settings['photos']:
        existing=next((a for a in CATALOG if a.get('salida')==entry['src'] and a['tipo']=='foto'),None)
        if existing:
            asset=dict(existing)
        else:
            from PIL import Image, ImageOps
            source=ROOT/entry['src']
            if source.stat().st_size > 20_000_000: raise ValueError('Image exceeds 20 MB')
            digest=hashlib.sha256(source.read_bytes()).hexdigest()[:16]
            with Image.open(source) as original:
                if original.width*original.height>40_000_000: raise ValueError('Image dimensions too large')
                im=ImageOps.exif_transpose(original).convert('RGB'); im.thumbnail((1920,1920))
                target=ROOT/f'assets/uploads/optimized-{digest}.webp'; target.parent.mkdir(exist_ok=True)
                im.save(target,'WEBP',quality=86)
                asset={'salida':target.relative_to(ROOT).as_posix(),'dimensiones':{'ancho':im.width,'alto':im.height},'categoria':'industria'}
                im.thumbnail((720,720)); target=ROOT/f'assets/uploads/thumb-{digest}.webp'; im.save(target,'WEBP',quality=82)
                asset.update(miniatura=target.relative_to(ROOT).as_posix(),dimensionesMiniatura={'ancho':im.width,'alto':im.height})
        asset.update(titulo=entry['caption'],descripcion=entry['alt'])
        identity=max(PHOTOS)+1; PHOTOS[identity]=asset; ids.append(identity)
    SERVICE_PHOTOS[page]=ids

def photo(id, thumb=False, extra=''):
    a=PHOTOS[id]; dims=a['dimensionesMiniatura' if thumb else 'dimensiones']; src=a['miniatura' if thumb else 'salida']
    return f'<img src="{src}" alt="{escape(a["descripcion"])}" width="{dims["ancho"]}" height="{dims["alto"]}" loading="lazy" decoding="async" {extra}>'

def photo_slider(ids, label='Galería FACAI', compact=False):
    slides=''.join(f'<figure class="photo-slide" data-slide data-category="{PHOTOS[i]["categoria"]}" aria-label="{n+1} de {len(ids)}"><a href="{PHOTOS[i]["salida"]}" data-photo data-caption="{escape(PHOTOS[i]["titulo"])}" aria-label="Ampliar: {escape(PHOTOS[i]["titulo"])}">{photo(i,compact)}<span class="photo-expand" aria-hidden="true">↗</span></a><figcaption>{escape(PHOTOS[i]["titulo"])}</figcaption></figure>' for n,i in enumerate(ids))
    return f'<div class="photo-slider {"slider-compact" if compact else "slider-large"}" data-slider role="region" aria-roledescription="carrusel" aria-label="{escape(label)}"><div class="slider-viewport"><div class="slider-track" data-slider-track>{slides}</div></div><div class="slider-controls"><button type="button" data-slide-prev aria-label="Foto anterior">←</button><span class="slider-counter" data-slide-counter>1 / {len(ids)}</span><button type="button" data-slide-next aria-label="Foto siguiente">→</button></div><div class="slider-progress" aria-hidden="true"><span></span></div><span class="sr-only" role="status" aria-live="polite" data-slide-announcement></span></div>'

def gallery(ids, title='La operación, en perspectiva.', filterable=False):
    categories={'all':'Todas','maquinaria':'Maquinaria','energia':'Energía','industria':'Industria','agua':'Agua e infraestructura'}
    filters='<div class="gallery-filters" role="group" aria-label="Filtrar imágenes por industria">'+''.join(f'<button type="button" data-gallery-filter="{k}" aria-pressed="{str(k=="all").lower()}">{v}</button>' for k,v in categories.items())+'</div>' if filterable else ''
    return f'<section class="photo-section section paper" data-gallery><div class="container"><div class="section-heading"><div><span class="eyebrow">UNA MIRADA A LAS SOLUCIONES</span><h2>{title}</h2></div><p>Recorre las imágenes a tu ritmo. Avanzan cada 5 segundos; también puedes usar las flechas o deslizar en tu teléfono.</p></div>{filters}{photo_slider(ids,title)}<p class="gallery-status">Imágenes de referencia · Encuadre completo · Selecciona una foto para ampliarla.</p></div></section>'

